package com.shopsphere;
import static org.junit.jupiter.api.Assertions.*;import java.math.BigDecimal;import java.util.UUID;import org.junit.jupiter.api.Test;import org.springframework.test.web.client.MockRestServiceServer;import org.springframework.web.client.RestClient;import static org.springframework.test.web.client.match.MockRestRequestMatchers.*;import static org.springframework.test.web.client.response.MockRestResponseCreators.*;
class HttpProductPricingGatewayTest{@Test void readsAuthoritativeProductAndPrice(){var b=RestClient.builder().requestInterceptor(CorrelationHeaders.interceptor());var server=MockRestServiceServer.bindTo(b).build();UUID id=UUID.randomUUID();server.expect(requestTo("http://products/api/products/"+id)).andExpect(header("X-Correlation-ID",org.hamcrest.Matchers.not(org.hamcrest.Matchers.blankOrNullString()))).andRespond(withSuccess("{\"id\":\""+id+"\",\"name\":\"Nova\",\"price\":499.00,\"imageUrls\":[\"/nova.jpg\"],\"active\":true}",org.springframework.http.MediaType.APPLICATION_JSON));var result=new HttpProductPricingGateway(b.baseUrl("http://products").build()).get(id);assertEquals(new BigDecimal("499.00"),result.currentPrice());assertEquals("Nova",result.name());server.verify();}@Test void mapsDownstreamFailureToBusinessError(){var b=RestClient.builder();var server=MockRestServiceServer.bindTo(b).build();UUID id=UUID.randomUUID();server.expect(requestTo("http://products/api/products/"+id)).andRespond(withServerError());assertThrows(BusinessException.class,()->new HttpProductPricingGateway(b.baseUrl("http://products").build()).get(id));}}
